var ARP_PRESET = [0xFFFF, 0x1111, 0xDDDD, 0x9595, 0xD5D5, 0x5D5D, 0xB5B5, 0x6B6B, 0xAB55, 0x5AD5, 0x7777, 0x76DB, 0x56DB, 0x5B5B, 0xEB55, 0x9249];
var NOTE = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
function arpScreen(g, v) {
  band(g, "clem-arp", [[10, "ARPEGGIATOR: 16 STEPS"], [560, "THE KEYS IT PLAYS"]]);
  var t = v.$touched || "", on = int(v, "arp_on", 0), pat = int(v, "arp_pattern", 0) & 15, mask = ARP_PRESET[pat];
  var tempo = int(v, "arp_tempo", 37), bpm = tempo === 0 ? null : 50 + (tempo - 1) * 250 / 126, beats = ARP_BEATS[int(v, "arp_clock", 12) & 15];
  var hp = t === "arp_pattern", i;
  // the pattern: a lamp a step, lit where a note starts
  for (i = 0; i < 16; i++) {
    var x = 12 + i * 33, lit = (mask >> i) & 1;
    g.fill(x, 22, 27, 18, lit ? (hp ? "slot" : on ? "#ff9a2e" : "#8a5216") : "#2a2a30");
    if (i % 4 === 0) g.text(x, 52, String(i + 1), DIMC, -1);
  }
  g.text(12, 64, (on ? (on === 2 ? "HOLD" : "ON") : "OFF") + "   PATTERN " + pat + (pat ? "" : ": EVERY STEP"), on ? CREAM : DIMC, -1);
  var stepS = bpm ? beats * 60 / bpm : null;
  g.text(12, 78, "A STEP " + txt(v, "arp_clock") + " AT " + (bpm ? Math.round(bpm) + " BPM = " + Math.round(stepS * 1000) + " MS" : "THE HOST'S TEMPO"),
    t === "arp_clock" || t === "arp_tempo" ? "slot" : CREAM, -1, 520);
  // the order: the keys held (or C, E, G as an example) over the range, as the engine walks them
  var lv = v.$live || {}, held = [], vs = lv.voices || [];
  for (i = 0; i < vs.length; i++) if (vs[i].held && held.indexOf(vs[i].note) < 0) held.push(vs[i].note);
  var ex = !held.length, keys = ex ? [60, 64, 67] : held.slice(0, 8), mode = int(v, "arp_order", 0), dir = int(v, "arp_dir", 0);
  var ord = keys.slice();
  if (mode === 0 || mode === 1) ord.sort(function (p, q) { return p - q; });
  var range = clamp(int(v, "arp_range", 1), 1, 10), seq = [];
  for (var o = 0; o < range; o++) for (i = 0; i < ord.length; i++) seq.push(ord[i] + 12 * o);
  if (mode === 1 || mode === 3) seq.reverse();
  var path = [], idx = -1, dirn = 1, N = Math.min(16, Math.max(8, seq.length * 2));
  for (i = 0; i < N; i++) {
    if (dir === 0) idx = idx < 0 ? 0 : (idx + 1) % seq.length;
    else if (dir === 1) idx = idx < 0 ? seq.length - 1 : (idx + seq.length - 1) % seq.length;
    else if (dir === 2) { if (idx < 0) { idx = 0; dirn = 1; } else if (seq.length > 1) { idx += dirn ? 1 : -1; if (idx >= seq.length) { idx = seq.length - 2; dirn = 0; } else if (idx < 0) { idx = 1; dirn = 1; } } }
    else { path = null; break; }
    path.push(seq[idx]);
  }
  var x0 = 566, w = 378, lo = Math.min.apply(null, seq), hi = Math.max.apply(null, seq), hd = /^arp_(order|dir|range)$/.test(t);
  if (!path) { g.text(x0 + w / 2, 52, "AT RANDOM AMONG " + seq.length + " NOTES", hd ? "slot" : CREAM, 0); }
  else {
    var cw = w / N;
    for (i = 0; i < N; i++) {
      var yy = 64 - (hi > lo ? (path[i] - lo) / (hi - lo) : 0.5) * 40;
      g.fill(x0 + i * cw + 1, yy, cw - 3, 4, hd ? "slot" : ex ? "#8a5216" : "#ff9a2e");
    }
    g.text(x0, 80, NOTE[lo % 12] + (Math.floor(lo / 12) - 1), DIMC, -1);
    g.text(x0 + w, 80, NOTE[hi % 12] + (Math.floor(hi / 12) - 1), DIMC, 1);
  }
  g.text(x0 + w / 2, 80, ex ? "C, E, G HELD (AN EXAMPLE)" : "THE KEYS HELD", DIMC, 0);
}
