// ---- MODIFIERS (mod_op): four operators, each two sources into one, matrix sources 25..28; the
// control delay (source 24) holds a source back by Time x 63 control steps of 8 samples at 40 kHz
var OP_SIGN = ["+", "-", "x", "/", "XOR", "OR", "AND", "S&H", "RAMP", "SWITCH", "ABS", "MIN", "MAX", "LAG", "FILTER", "DIFF"];
function opParam(op, p) {
  var sv = function (s) { var q = secs(s); return q[0] + " " + q[1].toUpperCase(); };
  switch (op) {
  case 7: return "EVERY " + sv(1.2 * Math.pow(2, (60 - p) / 12));
  case 8: return "UP IN " + sv(0.34 * Math.pow(2, (70 - p) / 12.2));
  case 9: return "ABOVE " + Math.round(p / 127 * 100) + "%";
  case 13: return (2.09 * Math.pow(2, (p - 64) / 11)).toFixed(2) + " /S";
  case 14: return "TAU " + sv(0.040 * Math.pow(2, (p - 100) / 25));
  }
  return null;
}
function modScreen(g, v) {
  band(g, "clem-mods", [[10, "MODIFIERS: TWO SOURCES MADE ONE"], [714, "WHERE EACH GOES"]]);
  var t = v.$touched || "";
  for (var m = 1; m <= 4; m++) {
    var y = 21 + (m - 1) * 14, a = int(v, "mod" + m + "_src1", 0), b = int(v, "mod" + m + "_src2", 0), op = int(v, "mod" + m + "_op", 0);
    var used = a || b || op, hot = t.indexOf("mod" + m + "_") === 0, ink = hot ? "slot" : used ? CREAM : DIMC;
    g.text(10, y + 4, String(m), hot ? "slot" : "#ff9a2e", -1);
    g.text(24, y + 4, used ? txt(v, "mod" + m + "_src1").toUpperCase() : "OFF", ink, -1, 190);
    g.fill(222, y - 4, 56, 11, used ? "#3a3a42" : "#26262c");
    g.text(250, y + 4, OP_SIGN[op] || "?", ink, 0);
    g.text(290, y + 4, used ? txt(v, "mod" + m + "_src2").toUpperCase() : "", ink, -1, 190);
    var pp = opParam(op, int(v, "mod" + m + "_par", 0));
    g.text(704, y + 4, used ? (pp || "P " + int(v, "mod" + m + "_par", 0)) : "", hot ? "slot" : DIMC, 1);
    g.text(486, y + 4, "->", DIMC, 0);
    g.text(500, y + 4, "MODIFIER " + m, used ? CREAM : DIMC, -1);
  }
  var ds = int(v, "mdelay_src", 0), dt = int(v, "mdelay_time", 0), hd = /^mdelay/.test(t);
  var y2 = 80, dsec = secs(dt * 63 * 8 / 40000);
  g.text(10, y2, "D", hd ? "slot" : "#ff9a2e", -1);
  g.text(24, y2, ds ? "CONTROL DELAY: " + txt(v, "mdelay_src").toUpperCase() + ", " + dsec[0] + " " + dsec[1].toUpperCase() + " LATER" : "CONTROL DELAY: OFF", hd ? "slot" : ds ? CREAM : DIMC, -1, 680);
  // where the modifiers and the delay go in the matrix
  var n = 0;
  for (var i = 1; i <= 16 && n < 5; i++) {
    var src = int(v, "m" + i + "_src", 0);
    if (src < 24 || src > 28) continue;
    var am = int(v, "m" + i + "_amt", 64) - 64;
    g.text(714, 26 + n * 13, (src === 24 ? "D" : String(src - 24)) + " > " + txt(v, "m" + i + "_dst").toUpperCase(), am ? CREAM : DIMC, -1, 190);
    g.text(944, 26 + n * 13, (am > 0 ? "+" : "") + am, am ? "#ff9a2e" : DIMC, 1);
    n++;
  }
  if (!n) g.text(714, 26, "NO MATRIX SLOT TAKES THEM", DIMC, -1);
}
