  if ((m = /^mix_(w1|w2|ring|noise|ext)$/.exec(key))) return { w1: "WAVE 1", w2: "WAVE 2", ring: "RING", noise: "NOISE", ext: "EXTERNAL" }[m[1]];
  if ((m = /^lfo\d_(rate|shape|delay|sync|sym|human|phase)$/.exec(key))) return { rate: "RATE", shape: "SHAPE", delay: "DELAY", sync: "SYNC", sym: "SYMM", human: "HUMAN", phase: "PHASE" }[m[1]];
  if ((m = /^m(\d+)_(src|amt|dst)$/.exec(key))) return { src: "SRC ", amt: "AMT ", dst: "DEST " }[m[2]] + m[1];
  if ((m = /^mod(\d)_(src1|src2|op|par)$/.exec(key))) return m[1] + { src1: " SRC A", src2: " SRC B", op: " TYPE", par: " PARAM" }[m[2]];
  if ((m = /^play_v(\d)$/.exec(key))) return "PLAY " + m[1];
