    volume: "VOLUME", amp_velo: "VELO", amp_keytrack: "KEYTRACK", pan: "PAN", pan_keytrack: "PAN KEYT", chorus: "CHORUS",
    fx_type: "EFFECT", glide_on: "GLIDE", glide_type: "TYPE", glide_mode: "MODE", glide_time: "TIME", alloc: "MODE", assign: "ASSIGN",
